//! Cargo-driven `ucx01000.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_FxDriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "FxDriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "FxDriverEntry", 0x7ffb00000000u64),
        o => panic!("ucx01000-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:chkstk", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        "x86_64" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        "aarch64" => &["import:wdfldr", "engine:c:libcntpr", "engine:pseh", "import:ntoskrnl", "import:hal", "engine:crate:wdfdriverentry-rust::TRUE", "engine:chkstk", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:cntpr_rust", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/usb/ucx01000",
        "drivers/usb/ucx01000",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/wdf/include/kmdf/1.17",
        "sdk/include/ucx/1.6",
        "vendor/wdf/shared/inc/private/common",
        "vendor/wdf/kmdf/inc/private",
        "sdk/lib/drivers/wdf_reactos/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "NTDDI_VERSION=0x06030000",
        "NTKRNLVISTA",
        "WDF_DEVICE_NO_WDMSEC_H",
        "WINVER=0x502",
        "_WIN32_WINNT=0x603",
    ];

    Linker::new(target_json)
        .c_from_compile_db("ucx01000_shims", &["drivers/usb/ucx01000/classlib.cpp", "drivers/usb/ucx01000/driver.cpp", "drivers/usb/ucx01000/exports.cpp"])
        .rc("drivers/usb/ucx01000/ucx01000.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("sdk/lib/drivers/wdfldr/wdfldr.spec", "wdfldr.sys", "wdfldr")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
